     3	final class EdgeRelaxer {
     4	
     5	    private final int[] dist;
     6	    private final int[] pred;
     7	
     8	    EdgeRelaxer(int vertices, int source) {
     9	        dist = new int[vertices];
    10	        pred = new int[vertices];
    11	        Arrays.fill(dist, Distances.UNREACHABLE);
    12	        Arrays.fill(pred, Distances.NO_PREDECESSOR);
    13	        dist[source] = 0;
    14	    }
    15	
    16	    boolean relax(WeightedEdge e) {
    17	        int u = e.from(), v = e.to(), w = e.weight();
    18	        if (dist[u] != Distances.UNREACHABLE && (long) dist[u] + w < dist[v]) {
    19	            dist[v] = dist[u] + w;
    20	            pred[v] = u;
    21	            return true;
    22	        }
    23	        return false;
    24	    }
    25	
    26	    boolean canRelax(WeightedEdge e) {
    27	        int u = e.from();
    28	        return dist[u] != Distances.UNREACHABLE
    29	            && (long) dist[u] + e.weight() < dist[e.to()];
    30	    }
    31	
    32	    // Records e.from() as the predecessor of e.to() without changing distances.
    33	    // Used during negative-cycle detection when the distance arrays must not be updated further.
    34	    void linkPredecessor(WeightedEdge e) {
    35	        pred[e.to()] = e.from();
    36	    }
    37	
    38	    int[] distances() { return dist; }
    39	
    40	    int[] predecessors() { return pred; }
    41	}
