     6	final class NegativeCycleDetector {
     7	
     8	    private final EdgeRelaxer relaxer;
     9	    private final List<WeightedEdge> edges;
    10	    private final int vertexCount;
    11	
    12	    NegativeCycleDetector(EdgeRelaxer relaxer, List<WeightedEdge> edges, int vertexCount) {
    13	        this.relaxer = relaxer;
    14	        this.edges = edges;
    15	        this.vertexCount = vertexCount;
    16	    }
    17	
    18	    Optional<NegativeCycle> detect() {
    19	        for (WeightedEdge e : edges) {
    20	            if (relaxer.canRelax(e)) {
    21	                relaxer.linkPredecessor(e);
    22	                return Optional.of(buildCycle(e.to()));
    23	            }
    24	        }
    25	        return Optional.empty();
    26	    }
    27	
    28	    private NegativeCycle buildCycle(int cycleEntry) {
    29	        int[] pred = relaxer.predecessors();
    30	
    31	        // Walk back vertexCount steps to guarantee landing inside the cycle
    32	        int x = cycleEntry;
    33	        for (int i = 0; i < vertexCount; i++) {
    34	            x = pred[x];
    35	        }
    36	
    37	        // Trace the cycle in predecessor order until we revisit x
    38	        List<Integer> traceback = new ArrayList<>();
    39	        int cur = x;
    40	        do {
    41	            traceback.add(cur);
    42	            cur = pred[cur];
    43	        } while (cur != x);
    44	
    45	        Collections.reverse(traceback);
    46	        return new NegativeCycle(traceback);
    47	    }
    48	}
